 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('jpac_sync_enrollment_progress','jpac_enforce_canonical_enrollment_progress') and pg_get_functiondef(p.oid) like '%m.status = ''published''%')<>2 then raise exception 'Safe Draft Isolation is not active';end if;
