 for r in select * from jsonb_to_recordset('[{"level":1,"num":2,"title":"Finding Middle C","objective":"Locate Middle C reliably and play it with steady timing and healthy technique.","lessons":[{"title":"Keyboard Landmarks","objective":"Use black-key groups to orient on the keyboard."},{"title":"Finding Middle C from Any Position","objective":"Locate Middle C repeatedly without prompting."},{"title":"Middle C Rhythm Control","objective":"Play Middle C in simple quarter- and half-note rhythms."}],"practiceTitle":"Middle C Landmark Drill","practiceInstructions":"Locate Middle C from three starting positions and play short counted rhythms.","challengeTitle":"Middle C Discovery Challenge","evidence":"Video, audio plus teacher observation, or live demonstration locating and playing Middle C accurately.","rubric":[{"name":"Keyboard landmark accuracy","weight":30},{"name":"Middle C identification","weight":25},{"name":"Rhythm and timing","weight":20},{"name":"Technique and control","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["keyboard geography","landmark strategy","timing","relaxed single-note attack","encouragement"],"concern":"Source URL appears malformed and requires review."},{"level":1,"num":3,"title":"Your First Pop Melody","objective":"Perform a five-note right-hand pop melody with steady quarter- and half-note rhythm.","lessons":[{"title":"Five-Note Hand Position","objective":"Place the right hand over an approved five-note range."},{"title":"Quarter and Half Notes","objective":"Differentiate and count quarter and half notes."},{"title":"Build the Pop Melody","objective":"Combine pitches and rhythm into a short melody."}],"practiceTitle":"Five-Note Melody Loop","practiceInstructions":"Practice the approved melody in short phrases with a slow steady pulse.","challengeTitle":"First Pop Melody Challenge","evidence":"Video or audio performance of the approved five-note melody plus a brief practice reflection.","rubric":[{"name":"Pitch accuracy","weight":30},{"name":"Rhythm accuracy","weight":25},{"name":"Hand position and technique","weight":20},{"name":"Steady pulse","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["right-hand placement","rhythm counting","phrase chunking","tempo confidence","mistake recovery"],"concern":"The named commercial-song video and repertoire licensing require review."},{"level":1,"num":4,"title":"R&B Bass Lines","objective":"Play a simple left-hand R&B bass pattern with steady groove and controlled movement.","lessons":[{"title":"Role of the Bass Line","objective":"Explain how bass supports harmony and rhythm."},{"title":"Left-Hand Pattern Shapes","objective":"Play an approved left-hand pattern accurately."},{"title":"Build a Slow R&B Groove","objective":"Maintain the pattern at a slow consistent tempo."}],"practiceTitle":"Left-Hand Groove Loop","practiceInstructions":"Loop a short bass pattern slowly, checking timing and relaxed movement.","challengeTitle":"R&B Bass Foundation Challenge","evidence":"Audio or video performance of a left-hand bass line with counted pulse and short groove reflection.","rubric":[{"name":"Bass-note accuracy","weight":30},{"name":"Groove and timing","weight":25},{"name":"Left-hand technique","weight":20},{"name":"Consistency","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["left-hand geography","groove","slow tempo","relaxed wrist","even attacks"],"concern":"The source overview video focuses on sound design rather than beginner piano and requires replacement review."},{"level":1,"num":5,"title":"Two Hands Together","objective":"Coordinate a simple melody and bass part using slow, deliberate hands-together practice.","lessons":[{"title":"Separate-Hand Preparation","objective":"Prepare each hand independently."},{"title":"Coordination by Small Sections","objective":"Combine one short phrase at a time."},{"title":"Tempo Progression","objective":"Increase tempo only after accurate repetitions."}],"practiceTitle":"Hands-Together Micro Loops","practiceInstructions":"Alternate separate-hand and hands-together repetitions of a short approved phrase.","challengeTitle":"Two-Hand Coordination Challenge","evidence":"Video or live demonstration of a simple melody and bass line together, including the practice tempo.","rubric":[{"name":"Hand coordination","weight":30},{"name":"Pitch accuracy","weight":25},{"name":"Rhythm and pulse","weight":20},{"name":"Technique and relaxation","weight":15},{"name":"Preparation and reflection","weight":10}],"aria":["hand independence","chunking","slow practice","coordination","confidence after errors"],"concern":"Source completion criterion of three mistake-free repetitions should not encourage unsafe perfectionism."},{"level":1,"num":6,"title":"Simple Pop Song on Piano","objective":"Create and perform a short original pop idea using a basic chord progression and melody.","lessons":[{"title":"I-V-vi-IV Chords","objective":"Play an approved four-chord progression."},{"title":"Melody over Harmony","objective":"Create a singable melody over the chords."},{"title":"Simple Song Form","objective":"Arrange a short verse/chorus form."}],"practiceTitle":"Pop Song Sketch","practiceInstructions":"Draft a chord loop and melody, record a rough take, and note one revision.","challengeTitle":"Simple Pop Song Challenge","evidence":"Audio or video of an original short pop piece showing chords, melody, and clear form.","rubric":[{"name":"Harmony and chord accuracy","weight":25},{"name":"Melody and musical fit","weight":25},{"name":"Rhythm and continuity","weight":20},{"name":"Creative form","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["chord transitions","melody fit","repetition","song form","creative encouragement"],"concern":"Source has Completion Criteria: None; criteria and lesson granularity are AI-PROPOSED. CapCut/Cakewalk are optional, not mastery requirements."},{"level":1,"num":7,"title":"Rock Piano Rhythms","objecti