":"Recorded or approved live full-song performance plus reflection.","rubric":[{"name":"Accuracy and continuity","weight":25},{"name":"Rhythm and coordination","weight":20},{"name":"Harmony and technique","weight":20},{"name":"Expression and musicality","weight":25},{"name":"Preparation and reflection","weight":10}],"aria":["integration","endurance","transitions","recovery","performance confidence"],"concern":"Repertoire length, licensing, and difficulty require teacher approval."},{"level":3,"num":1,"title":"Seventh Chords and Extensions","objective":"Construct and use seventh chords and selected extensions in expressive progressions.","lessons":[{"title":"Seventh-Chord Construction","objective":"Build common seventh-chord qualities."},{"title":"Add 9ths, 11ths, and 13ths","objective":"Add appropriate chord extensions."},{"title":"Voice Extended Progressions","objective":"Voice a progression with clarity and smooth motion."}],"practiceTitle":"Extension Voicing Lab","practiceInstructions":"Create and compare three voicings for an approved progression.","challengeTitle":"Extended Harmony Challenge","evidence":"Audio/video progression using seventh chords and extensions with harmonic explanation.","rubric":[{"name":"Chord construction","weight":30},{"name":"Extension accuracy","weight":25},{"name":"Voice leading","weight":20},{"name":"Musical application","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["chord spelling","extension choice","voicing clarity","voice leading"],"concern":"Source does not define a single required extension set or voicing range."},{"level":3,"num":2,"title":"Modes and Modal Interchange","objective":"Recognize modal colors and use borrowed harmony in a short musical context.","lessons":[{"title":"Mode Color and Character","objective":"Compare selected modes by characteristic tones."},{"title":"Borrowed Chords","objective":"Identify chords borrowed from a parallel mode."},{"title":"Modal Interchange in a Progression","o