ping for contemporary or jazz contexts.","lessons":[{"title":"Shell and Rootless Concepts","objective":"Construct selected advanced voicings."},{"title":"Voice Leading with Extensions","objective":"Move smoothly through a progression."},{"title":"Responsive Comping Rhythms","objective":"Comp with rhythmic space and support."}],"practiceTitle":"Voicing and Comping Cycle","practiceInstructions":"Rotate voicings through a progression, then vary rhythmic placement.","challengeTitle":"Advanced Comping Challenge","evidence":"Audio/video comping performance supporting a track or collaborator, with voicing notes.","rubric":[{"name":"Voicing accuracy","weight":30},{"name":"Voice leading","weight":25},{"name":"Comping rhythm","weight":20},{"name":"Support and dynamics","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["shells","extensions","register","rhythmic space","ensemble awareness"],"concern":"Rootless voicing expectations and collaborator/backing source require teacher approval."},{"level":3,"num":5,"title":"Blues Licks and Soloing","objective":"Develop, vary, and connect idiomatic blues licks into an expressive solo.","lessons":[{"title":"Learn Licks by Ear","objective":"Accurately learn approved blues vocabulary."},{"title":"Variation and Transposition","objective":"Transform rhythm, ending, or key."},{"title":"Build a Solo Arc","objective":"Connect ideas into a coherent solo."}],"practiceTitle":"Blues Lick Variation Practice","practiceInstructions":"Record one lick, two variations, and a connected phrase.","challengeTitle":"Advanced Blues Solo Challenge","evidence":"Audio/video blues solo using learned and varied vocabulary with reflection.","rubric":[{"name":"Vocabulary accuracy","weight":20},{"name":"Phrasing and rhythm","weight":25},{"name":"Development and variation","weight":25},{"name":"Expression and form","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["ear learning","articulation","motif variation","form","ori