er control","weight":25},{"name":"Phrasing and rhythm","weight":20},{"name":"Creativity and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["characteristic tones","tonal center","harmonic fit","phrase development"],"concern":"Backing tracks and exact modal requirements need teacher approval."},{"level":3,"num":8,"title":"Introduction to Jazz Piano","objective":"Apply foundational jazz harmony, rhythm, and improvisational interaction.","lessons":[{"title":"Jazz Form and Listening","objective":"Identify basic jazz form and ensemble roles."},{"title":"Core Progressions and Voicings","objective":"Play a selected jazz progression."},{"title":"First Jazz Conversation","objective":"Create responsive phrases with space and swing."}],"practiceTitle":"Jazz Conversation Practice","practiceInstructions":"Alternate comping and short improvised responses over a simple form.","challengeTitle":"Intro Jazz Piano Challenge","evidence":"Audio/video jazz performance demonstrating chords, rhythm, and a short improvisation.","rubric":[{"name":"Harmony and form","weight":25},{"name":"Jazz rhythm and feel","weight":25},{"name":"Improvisation","weight":20},{"name":"Interaction and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["listening","ii-V-I","swing","call and response","stylistic respect"],"concern":"Repertoire, swing interpretation, and historical context require teacher curation."},{"level":3,"num":9,"title":"Rhythmic Independence","objective":"Maintain contrasting rhythmic roles between hands with control and musical flow.","lessons":[{"title":"Independent Subdivisions","objective":"Perform each rhythmic layer separately."},{"title":"Layer Contrasting Patterns","objective":"Combine contrasting patterns gradually."},{"title":"Apply Independence Musically","objective":"Use independence in a short musical texture."}],"practiceTitle":"Layered Rhythm Ladder","practiceInstructions":"Add one rhythmic layer at a time at a safe tempo.","challengeTitle":"Rhythmic Independence Challenge","evidence":"Video/audio of contrasting hand rhythms in an exercise and musical excerpt.","rubric":[{"name":"Rhythmic accuracy","weight":30},{"name":"Hand independence","weight":25},{"name":"Pulse stability","weight":20},{"name":"Technique and control","weight":15},{"name":"Reflection and completeness","weight":10}],"aria":["subdivision","layered practice","polyrhythm preparation","tension monitoring"],"concern":"Exact rhythmic ratios and difficulty progression are not standardized in source."},{"level":3,"num":10,"title":"Arranging a Pop Song","objective":"Transform a pop song into a coherent piano arrangement with personal musical choices.","lessons":[{"title":"Analyze Song Structure","objective":"Map form, melody, harmony, and key moments."},{"title":"Design Piano Texture","objective":"Choose accompaniment and register by section."},{"title":"Refine the Full Arrangement","objective":"Create transitions and a complete performance plan."}],"practiceTitle":"Arrangement Blueprint","practiceInstructions":"Draft a section-by-section texture map and record a short prototype.","challengeTitle":"Pop Song Arrangement Challenge","evidence":"Audio/video of an original or licensed pop-song arrangement with arrangement notes.","rubric":[{"name":"Structural clarity","weight":20},{"name":"Harmony and melody","weight":25},{"name":"Texture and transitions","weight":25},{"name":"Creativity and expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["form analysis","texture","register","transitions","personal voice"],"concern":"Copyright/repertoire permissions and use of commercial material require review."},{"level":3,"num":11,"title":"Intro to Jazz Comping","objective":"Comp through a jazz blues or progression using shell voicings and interactive rhythm.","lessons":[{"title":"Role of Jazz Comping","objective":"Explain the pianist''s supporting role."},{"title":"Shell Voicings","objec