0},{"name":"Voice leading","weight":25},{"name":"Harmonic coherence","weight":20},{"name":"Performance clarity","weight":15},{"name":"Process and completeness","weight":10}],"aria":["contrary motion","independence","consonance/dissonance","notation access"],"concern":"Source does not specify species/rule system; criteria are AI-PROPOSED."},{"level":4,"num":3,"title":"Advanced Improvisation Techniques","objective":"Develop long-form improvisation through motif, harmony, rhythm, and narrative shape.","lessons":[{"title":"Motivic Development","objective":"Transform a motif across phrases."},{"title":"Harmonic Navigation","objective":"Target chord tones through changes."},{"title":"Build a Solo Narrative","objective":"Shape tension, release, and pacing."}],"practiceTitle":"Motif Development Lab","practiceInstructions":"Create one motif and develop it through rhythm, register, and harmony.","challengeTitle":"Advanced Improvisation Challenge","evidence":"Audio/video extended improvisation with short analysis of development choices.","rubric":[{"name":"Harmonic navigation","weight":25},{"name":"Motivic development","weight":25},{"name":"Rhythm and phrasing","weight":20},{"name":"Narrative expression","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["motif","chord-tone targeting","pacing","risk-taking","recovery"],"concern":"Length, harmonic form, and accompaniment source require teacher approval."},{"level":4,"num":4,"title":"Gospel and R&B Piano Mastery","objective":"Perform an advanced Gospel/R&B arrangement with stylistic harmony, groove, and expression.","lessons":[{"title":"Genre Language and Context","objective":"Identify stylistic harmonic and rhythmic features respectfully."},{"title":"Advanced Chord Movement","objective":"Use passing chords and advanced movement."},{"title":"Build and Shape the Arrangement","objective":"Create dynamic builds and expressive flow."}],"practiceTitle":"Gospel and R&B Progression Study","practiceInstructions":"Practice approved movements in context and annotate stylistic choices.","challengeTitle":"Gospel and R&B Mastery Challenge","evidence":"Audio/video arrangement or original piece demonstrating harmony, groove, and expressive arc.","rubric":[{"name":"Stylistic harmony","weight":25},{"name":"Groove and timing","weight":25},{"name":"Arrangement and development","weight":20},{"name":"Expression and technique","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["passing chords","call and response","dynamic builds","cultural context"],"concern":"Cultural context, repertoire, and worship-specific material require qualified review."},{"level":4,"num":5,"title":"Artist Study: Stevie Wonder","objective":"Analyze and apply selected Stevie Wonder musical characteristics in an original tribute study.","lessons":[{"title":"Listen and Analyze","objective":"Identify selected compositional and keyboard traits."},{"title":"Harmony, Groove, and Melody","objective":"Practice an approved stylistic device."},{"title":"Create an Original Tribute","objective":"Create original music inspired without copying."}],"practiceTitle":"Stevie Wonder Style Study","practiceInstructions":"Analyze one approved excerpt and transform one characteristic into an original sketch.","challengeTitle":"Stevie Wonder Artist Study Challenge","evidence":"Original audio/video tribute plus analysis citing studied musical features.","rubric":[{"name":"Analysis and understanding","weight":25},{"name":"Stylistic application","weight":25},{"name":"Originality","weight":25},{"name":"Performance and groove","weight":15},{"name":"Reflection and attribution","weight":10}],"aria":["listening analysis","groove","chromatic harmony","attribution","originality"],"concern":"Copyright, source attribution, and avoiding imitation require explicit teacher guidance."},{"level":4,"num":6,"title":"Artist Study: Bill Evans","objective":"Analyze and apply selected Bill Evans voicing, touch, and interaction concepts in a