},{"name":"Reflection and completeness","weight":10}],"aria":["listening","balance","cues","adaptability","supportive role"],"concern":"Collaborator access requires approved backing-track or teacher-observed alternative."},{"level":4,"num":8,"title":"Playing in a Band","objective":"Perform a pianist''s band role with rhythmic lock, communication, and adaptable texture.","lessons":[{"title":"Rhythm-Section Lock","objective":"Coordinate with bass and drums."},{"title":"Cues and Musical Communication","objective":"Use visual and musical cues appropriately."},{"title":"Shape a Band Arrangement","objective":"Adjust register and density across sections."}],"practiceTitle":"Band-Rehearsal Simulation","practiceInstructions":"Practice with an approved ensemble, track, or simulated rhythm section and mark cues.","challengeTitle":"Band Performance Challenge","evidence":"Live/recorded ensemble or approved simulation demonstrating lock, cues, and role awareness.","rubric":[{"name":"Time and groove","weight":25},{"name":"Listening and interaction","weight":25},{"name":"Part accuracy","weight":20},{"name":"Communication and adaptability","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["pocket","cues","register","arrangement role","recovery"],"concern":"Actual ensemble access and backing materials require equitable alternatives."},{"level":4,"num":9,"title":"Rock & R&B Organ Techniques","objective":"Apply organ-specific sound controls, comping patterns, and gestures safely on an available keyboard.","lessons":[{"title":"Organ Sound and Controls","objective":"Explain drawbar/rotary concepts using available controls."},{"title":"Comping and Riffs","objective":"Play selected organ comping patterns."},{"title":"Safe Organ Articulation","objective":"Use approved gestures without unsafe force."}],"practiceTitle":"Organ Texture Practice","practiceInstructions":"Explore two organ registrations and practice an approved riff/comping pattern.","challengeTitle":"Rock and R&B Organ Challenge","evidence":"Audio/video organ-style performance on available equipment with sound-choice explanation.","rubric":[{"name":"Organ sound control","weight":20},{"name":"Pattern and note accuracy","weight":25},{"name":"Groove and timing","weight":25},{"name":"Technique and style","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["registration","rotary effect","comping","palm smear safety","glissando safety"],"concern":"Hardware varies; palm smears/glissandos must be optional and safety-reviewed."},{"level":4,"num":10,"title":"Professional Performance Skills","objective":"Prepare and deliver a professional-quality performance with reliable technique, communication, and recovery.","lessons":[{"title":"Professional Preparation","objective":"Create a technical and logistical performance plan."},{"title":"Stage Communication","objective":"Communicate musical intent to an audience."},{"title":"Performance Recovery and Review","objective":"Recover from errors and evaluate the result."}],"practiceTitle":"Professional Run-Through","practiceInstructions":"Complete a timed setup, sound check simulation, performance, and review.","challengeTitle":"Professional Performance Challenge","evidence":"Polished live/recorded performance plus preparation checklist and self-evaluation.","rubric":[{"name":"Technical reliability","weight":25},{"name":"Musical communication","weight":25},{"name":"Stage readiness","weight":20},{"name":"Recovery and professionalism","weight":20},{"name":"Reflection and completeness","weight":10}],"aria":["preparation","stage presence","recovery","sound check","audience communication"],"concern":"Venue, equipment, and accessibility expectations require individualized planning."},{"level":4,"num":11,"title":"The Working Musician","objective":"Create a practical pianist career plan covering opportunities, professionalism, promotion, and basic finances.","lessons":[{"title":"Pianist Career Options","objective":"Compare relevant performance and creative roles."},{"title":"Professional Communication and Networking","objective":"Prepare professional outreach and conduct standards."},{"title":"Build a Working-Musician Plan","objective":"Draft goals, materials, and a basic budget."}],"practiceTitle":"Musician Career Planning Practice","practiceInstructions":"Draft a one-page opportunity map, outreach message, and next-step checklist.","challengeTitle":"Working Musician Portfolio Challenge","evidence":"Career plan plus approved professional artifact and teacher/staff review evidence.","rubric":[{"name":"Career understanding","weight":20},{"name":"Professional plan","weight":25},{"name":"Communication artifact","weight":20},{"name":"Practical readiness","weight":25},{"name":"Reflection and completeness","weight":10}],"aria":["career pathways","networking","budgeting","marketing","boundaries"],"concern":"Financial/legal guidance must remain educational; local opportunity claims require review."},{"level":4,"num":12,"title":"Final Capstone: The Master Recital","objective":"Plan, arrange, and perform a 15-minute recital of contrasting works demonstrating artistic identity and mastery.","lessons":[{"title":"Design the Recital Program","objective":"Select contrasting repertoire and justify the program."},{"title":"Rehearse, Arrange, and Produce","objective":"Prepare arrangements, transitions, and production details."},{"title":"Perform and Evaluate the Master Recital","objective":"Deliver and critically evaluate the complete recital."}],"practiceTitle":"Master Recital Production Rehearsal","practiceInstructions":"Run the full program with transitions, timing, recording setup, and contingency plan.","challengeTitle":"Master Recital Capstone Challenge","evidence":"Professional-quality live/recorded approximately 15-minute recital with three contrasting pieces, at least one original arrangement, program notes, and reflection.","rubric":[{"name":"Program design and preparation","weight":20},{"name":"Technical and musical mastery","weight":25},{"name":"Contrast and artistic identity","weight":20},{"name":"Performance professionalism","weight":25},{"name":"Reflection and documentation","weight":10}],"aria":["program design","endurance","transitions","artistic identity","production planning"],"concern":"Repertoire rights, duration accommodations, venue/equipment, and alternative evidence require leadership and teacher approval."}]'::jsonb) as x(level int,num int,title text,objective text,lessons jsonb,"practiceTitle" text,"practiceInstructions" text,"challengeTitle" text,evidence text,rubric jsonb,aria jsonb,concern text) order by level,num loop
  select id into v_level from public.course_levels where course_id=v_course and level_number=r.level;
  if v_level is null then
   v_level:=('623ef115-ecf7-437f-87a9-6b60052f1cce'::uuid); if r.level=3 then v_level:='c5520691-7461-46b8-8808-ed9f28ffb02a';elsif r.level=4 then v_level:='44617e46-d7c4-4b06-8786-1e8d51153089';end if;
   insert into public.course_levels(id,course_id,level_number,title,description,learning_objectives,status,core_xp_target,review_notes) values(v_level,v_course,r.level,(array['Beginner','Intermediate','Advanced','Master'])[r.level],(array['Beginner','Intermediate','Advanced','Master'])[r.level]||' Piano curriculum. Draft review only.',array['Complete the source-aligned Piano level curriculum.'],'draft',6250,'Piano full draft rollout 202608130001; metadata target reconciliation deferred.');
  elsif r.level=1 and not exists(select 1 from public.course_levels where id=v_level and course_id=v_course and level_number=1 and title='Beginner' and description='Beginner Piano foundations. Draft review only.' and learning_objectives=array['Build healthy setup and foundational keyboard control.']::text[] and status='draft' and core_xp_target=6250 and review_notes='Piano Module 1 pilot; AI-PROPOSED content requires leadership and piano-teacher review.' and approved_by is null and approved_at is null) then raise exception 'Piano Level 1 exact reuse conflict';
  elsif r.level>1 and not exists(select 1 from public.course_levels where id=v_level and course_id=v_course and level_number=r.level and title=(array['Beginner','Intermediate','Advanced','Master'])[r.level] and description=(array['Beginner','Intermediate','Advanced','Master'])[r.level]||' Piano curriculum. Draft review only.' and learning_objectives=array['Complete the source-aligned Piano level curriculum.']::text[] and status='draft' and core_xp_target=6250 and review_notes='Piano full draft rollout 202608130001; metadata target reconciliation deferred.' and approved_by is null and approved_at is null) then raise exception 'Piano Level % exact reuse conflict',r.level;end if;
  v_ids:=v_ids;v_id:=v_ids->(r.level||'.'||r.num);select id into v_module from public.course_modules where course_level_id=v_level and level_module_number=r.num;
  if v_module is null then
   v_module:=(v_id->>'module')::uuid;
   if exists(select 1 from public.course_modules where course_id=v_course and (sort_order=(r.level-1)*12+r.num or title=r.title)) then raise exception 'Piano module identity conflict %.%',r.level,r.num;end if;
   insert into public.course_modules(id,course_id,course_level_id,level_module_number,title,description,short_intro,sort_order,xp_value,core_xp,intro_core_xp,video_core_xp,assignment_core_xp,mastery_core_xp,core_unlock_threshold,bonus_xp_available,jpac_tool_activity,real_world_activity,career_connection,portfolio_moment,status,video_brief,aria_coaching_targets,career_mission_ideas,review_notes)
   values(v_module,v_course,v_level,r.num,r.title,r.objective,r.objective,(r.level-1)*12+r.num,625,625,50,100,350,125,438,0,jsonb_build_object('review_status','NEEDS CATALOG REVIEW'),jsonb_build_object('title',r."practiceTitle",'instructions',r."practiceInstructions"),'',false,'draft','NEEDS REVIEW: no media is activated.',jsonb_build_object('advisory_only',true,'targets',r.aria,'prohibited',jsonb_build_array('assess','approve','award XP','grant mastery','unlock')),'[]','Piano full draft rollout 202608130001; AI-PROPOSED; NEEDS TEACHER REVIEW; Career Path NOT CONFIGURED. '||r.concern);
  elsif not exists(select 1 from public.course_modules where id=v_module and course_id=v_course and course_level_id=v_level and level_module_number=r.num and title=r.title and description=r.objective and short_intro=r.objective and sort_order=(r.level-1)*12+r.num and xp_value=625 and core_xp=625 and intro_core_xp=50 and video_core_xp=100 and assignment_core_xp=350 and mastery_core_xp=125 and core_unlock_threshold=438 and bonus_xp_available=0 and jpac_tool_activity=jsonb_build_object('review_status','NEEDS CATALOG REVIEW') and real_world_activity=jsonb_build_object('title',r."practiceTitle",'instructions',r."practiceInstructions") and career_connection='' and not portfolio_moment and status='draft' and video_brief='NEEDS REVIEW: no media is activated.' and lab_tool_id is null and active_instructional_media_id is null and primary_video_url is null and approved_by is null and approved_at is null and review_notes='Piano full draft rollout 202608130001; AI-PROPOSED; NEEDS TEACHER REVIEW; Career Path NOT CONFIGURED. '||r.concern) then raise exception 'Piano module payload conflict %.%',r.level,r.num;end if;
  v_rubric:=jsonb_build_object('criteria',(select jsonb_agg(jsonb_build_object('name',x->>'name','weight',(x->>'weight')::int,'bands',jsonb_build_object('Exceeds','Consistently exceeds the approved standard.','Meets','Meets the approved standard.','Developing','Partially meets the standard.','Not Yet','Does not yet meet the standard.')) order by ord) from jsonb_array_elements(r.rubric) with ordinality q(x,ord)));
  if exists(select 1 from public.lessons where module_id=v_module) or exists(select 1 from public.activities where module_id=v_module) then
   if (select count(*) from public.lessons where module_id=v_module)<>3 or (select count(*) from public.activities where module_id=v_module)<>2
    or exists(select 1 from jsonb_array_elements(r.lessons) with ordinality expected(item,ord) left join public.lessons l on l.module_id=v_module and l.sort_order=ord where l.id is null or l.title is distinct from expected.item->>'title' or l.learning_objective is distinct from expected.item->>'objective' or l.description is distinct from expected.item->>'objective' or l.status is distinct from 'draft' or l.xp_value<>0)
    or not exists(select 1 from public.activities where module_id=v_module and title=r."practiceTitle" and activity_type='practice' and instructions=r."practiceInstructions" and submission_type='none' and xp_reward=0 and xp_type='bonus' and not required and status='draft' and passing_score=70 and allows_resubmission and not portfolio_candidate and not certificate_eligible)
    or not exists(select 1 from public.activities where module_id=v_module and title=r."challengeTitle" and activity_type='performance' and instructions=r.evidence||' Use the existing JPAC submission and teacher-review workflow.' and submission_type='video' and xp_reward=350 and xp_type='core' and required and status='draft' and passing_score=70 and allows_resubmission and rubric=v_rubric and not portfolio_candidate and not certificate_eligible)
   then raise exception 'Existing child payload conflict %.%',r.level,r.num;end if;
  else
   for i in 0..2 loop v_lesson:=r.lessons->i;insert into public.lessons(id,module_id,title,description,lesson_type,duration_minutes,sort_order,xp_value,status,short_summary,learning_objective,content_blocks,technique_cues,common_mistakes,self_check,resource_brief)
    values((v_id->'lessons'->>i)::uuid,v_module,v_lesson->>'title',v_lesson->>'objective','interactive',25,i+1,0,'draft',v_lesson->>'objective',v_lesson->>'objective',jsonb_build_array(v_lesson->>'objective','Practice slowly with teacher-approved adaptations.','Reflect on one strength and one next step.'),array['Control before speed','Release unnecessary tension','ARIA is advisory only'],array['Rushing','Ignoring tension','Skipping reflection'],'Can you demonstrate the objective and name one next step?','AI-PROPOSED accessibility alternatives require teacher review.');end loop;
